diff --git a/runtime/nvidia/op_attention_sm90.cuh b/runtime/nvidia/op_attention_sm90.cuh
index ba268a69..ec175e36 100644
--- a/runtime/nvidia/op_attention_sm90.cuh
+++ b/runtime/nvidia/op_attention_sm90.cuh
@@ -64,6 +64,9 @@

 /* Default K/V pipeline uses two slots, with tile t+1 loading under tile t's math. */
 #define FA_SM90_NS 2
+#ifndef PLOW_NV_FA512_SINGLE_QK
+#define PLOW_NV_FA512_SINGLE_QK 0
+#endif
 #ifndef PLOW_NV_FA512_KV64
 #define PLOW_NV_FA512_KV64 0
 #endif
@@ -579,6 +582,7 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric
     constexpr int KS0 = HD / 16;       /* GEMM0 k16 steps (contract over HD)            */
     constexpr int QK_UNROLL = PLOW_NV_FA_QK_UNROLL;
     constexpr int NSTAGE = FA_SM90_STAGES(HD, BKV);
+    constexpr bool SINGLE_QK = PLOW_NV_FA512_SINGLE_QK && HD == 512;
     constexpr int PV_UNROLL = NSTAGE == 1 ? 4 : 1;
     constexpr int KS1 = BKV / 16;      /* GEMM1 k16 steps (contract over BKV)           */
     constexpr int NB0 = BKV / 8;       /* n8 blocks in the score accumulator            */
@@ -792,6 +796,8 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric
             /* --- GEMM0: S[64][BKV] = Q . K^T. scale-d = 0 on the first k-step seeds the
              * accumulator, so no zeroing pass. --- */
             const __nv_bfloat16* kbuf = Ks + (size_t)sb * NSUB * KT;
+            float cA, cB;
+            if (!SINGLE_QK || wg == 0) {
             float S[BKV / 2];
             sm90_wg_fence();
 #pragma unroll QK_UNROLL
@@ -832,8 +838,8 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric

             const float mnA = fmaxf(mA, mxA), mnB = fmaxf(mB, mxB);
             /* corr==0 on the first attended tile (m_old still -inf) — the shared body's rule. */
-            const float cA = (mA == FA_NEG_INF) ? 0.0f : FA_EXP(mA - mnA);
-            const float cB = (mB == FA_NEG_INF) ? 0.0f : FA_EXP(mB - mnB);
+            cA = (mA == FA_NEG_INF) ? 0.0f : FA_EXP(mA - mnA);
+            cB = (mB == FA_NEG_INF) ? 0.0f : FA_EXP(mB - mnB);
             mA = mnA;
             mB = mnB;

@@ -864,6 +870,23 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric
             sB += __shfl_xor_sync(0xffffffffu, sB, 2);
             lA = lA * cA + sA;
             lB = lB * cB + sB;
+            if constexpr (SINGLE_QK) {
+                // QK has drained; its K slot can carry row statistics until the next tile.
+                float* stats = (float*)kbuf;
+                if ((lane & 3) == 0) {
+                    stats[3 * rA] = mA; stats[3 * rA + 1] = lA; stats[3 * rA + 2] = cA;
+                    stats[3 * rB] = mB; stats[3 * rB + 1] = lB; stats[3 * rB + 2] = cB;
+                }
+            }
+            }
+            if constexpr (SINGLE_QK) {
+                __syncthreads();
+                if (wg == 1) {
+                    const float* stats = (const float*)kbuf;
+                    mA = stats[3 * rA]; lA = stats[3 * rA + 1]; cA = stats[3 * rA + 2];
+                    mB = stats[3 * rB]; lB = stats[3 * rB + 1]; cB = stats[3 * rB + 2];
+                }
+            }

             /* Rescale O on the SAME two rows this lane owns — two scalars, no smem, and by
              * construction the same (row,col) map GEMM0 used. */
@@ -885,7 +908,7 @@ __device__ void d_flash_prefill_sm90(float* __restrict__ Opart, float* __restric
              * cumulativity — NOT the CUTLASS producer-side order (fence-before-barrier), which would
              * only fence wg0. Do not swap these two lines: moving the fence above the barrier drops
              * the ordering guarantee for wg1's reads of wg0's Ps. */
-            __syncthreads(); /* (B) Ps published to the whole block */
+            if constexpr (!SINGLE_QK) __syncthreads(); /* (B) Ps published to the whole block */
             fa90_async_proxy_fence();

             /* --- GEMM1: O += P . V. A = Ps (K-major over BKV, swizzle-0); B = V MN-MAJOR
